insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c4000000-0000-0000-0000-000000000001', 'ukmla', 'b845872a-b6a9-4b99-9a2a-b4ce2d946cf1',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c4000000-0000-0000-0000-000000000001', 'A', 'Insert a nasopharyngeal airway', false, 'Ruled out because the periorbital bruising and clear rhinorrhoea suggest a base of skull fracture, which is a contraindication to nasopharyngeal airway insertion due to the risk of intracranial placement.', 1),
('c4000000-0000-0000-0000-000000000001', 'B', 'Perform an immediate surgical cricothyroidotomy', false, 'Ruled out because this is reserved for a failed airway (cannot intubate, cannot oxygenate), not as a first-line manoeuvre before basic airway techniques have been tried.', 2),
('c4000000-0000-0000-0000-000000000001', 'C', 'Continue high-flow oxygen via non-rebreathe mask and reassess in 15 minutes', false, 'Ruled out because an obstructed airway with hypoxia requires immediate action, not a delayed reassessment.', 3),
('c4000000-0000-0000-0000-000000000001', 'D', 'Perform a jaw thrust and insert an oropharyngeal (Guedel) airway, preparing for early definitive airway management given the reduced GCS', true, 'Correct. Airway obstruction with a reduced GCS requires immediate basic airway manoeuvres as a bridge while preparing for a definitive (intubated) airway.', 4),
('c4000000-0000-0000-0000-000000000001', 'E', 'Sit the patient upright to improve air entry', false, 'Ruled out because this is contraindicated with a suspected spinal injury and does not address the underlying airway obstruction.', 5),
('c4000000-0000-0000-0000-000000000002', 'A', 'Urgent portable chest X-ray to confirm the diagnosis before treatment', false, 'Ruled out because tension pneumothorax should be treated immediately based on clinical findings; waiting for imaging delays life-saving treatment.', 1),
('c4000000-0000-0000-0000-000000000002', 'B', 'Immediate needle or finger thoracostomy of the left chest', true, 'Correct. Tension pneumothorax is a clinical diagnosis (tracheal deviation, absent breath sounds, hyperresonance, distended neck veins, haemodynamic compromise) that requires immediate decompression, followed by a chest drain.', 2),
('c4000000-0000-0000-0000-000000000002', 'C', 'Intravenous fluid bolus alone', false, 'Ruled out because fluids do not relieve the underlying obstruction to venous return caused by the tension pneumothorax.', 3),
('c4000000-0000-0000-0000-000000000002', 'D', 'Pericardiocentesis', false, 'Ruled out because this is the treatment for cardiac tamponade, not tension pneumothorax; the clinical signs here (absent breath sounds, hyperresonance, tracheal deviation) point to the chest, not the pericardium.', 4),
('c4000000-0000-0000-0000-000000000002', 'E', 'Intubation and positive-pressure ventilation without decompressing the chest first', false, 'Ruled out because positive-pressure ventilation can rapidly worsen an undrained tension pneumothorax.', 5),
('c4000000-0000-0000-0000-000000000003', 'A', 'Continue large volumes of crystalloid until his blood pressure normalises before surgery', false, 'Ruled out because over-resuscitation with crystalloid worsens dilutional coagulopathy and delays definitive haemorrhage control.', 1),
('c4000000-0000-0000-0000-000000000003', 'B', 'Wait for fully cross-matched blood before giving any transfusion', false, 'Ruled out because emergency group O-negative or group-specific blood should be given while formal cross-match is pending in an unstable bleeding patient.', 2),
('c4000000-0000-0000-0000-000000000003', 'C', 'Arrange outpatient CT follow-up as his GCS is normal', false, 'Ruled out because he has haemodynamically significant intra-abdominal haemorrhage requiring immediate inpatient management, not outpatient follow-up.', 3),
('c4000000-0000-0000-0000-000000000003', 'D', 'Give a single dose of tranexamic acid only, with no further action needed', false, 'Ruled out because tranexamic acid is an adjunct given early in trauma haemorrhage, not a substitute for the major haemorrhage protocol and surgical source control.', 4),
('c4000000-0000-0000-0000-000000000003', 'E', 'Activate the major haemorrhage protocol and give blood products in a balanced ratio while arranging urgent surgical control of bleeding', true, 'Correct. Haemorrhagic shock unresponsive to initial crystalloid should trigger the major haemorrhage protocol with early balanced blood product transfusion and urgent source control, rather than further crystalloid.', 5),
('c4000000-0000-0000-0000-000000000004', 'A', 'Remove the collar and ask her to actively move her neck to assess range of motion', false, 'Ruled out because active range-of-motion testing is contraindicated in the presence of midline bony tenderness.', 1),
('c4000000-0000-0000-0000-000000000004', 'B', 'Arrange plain cervical spine X-rays only, with no CT required', false, 'Ruled out because CT is preferred over plain films in patients meeting high-risk imaging criteria.', 2),
('c4000000-0000-0000-0000-000000000004', 'C', 'Maintain in-line spinal immobilisation and arrange CT of the cervical spine', true, 'Correct. Midline cervical spine tenderness following a dangerous mechanism is an indication for CT cervical spine imaging (rather than plain films) under NICE head/spinal injury guidance.', 3),
('c4000000-0000-0000-0000-000000000004', 'D', 'Reassure and discharge with no imaging required', false, 'Ruled out because midline tenderness after a dangerous mechanism warrants imaging before clearance.', 4),
('c4000000-0000-0000-0000-000000000004', 'E', 'Remove spinal immobilisation since her GCS is 15', false, 'Ruled out because a normal GCS does not exclude a significant cervical spine injury.', 5),
('c4000000-0000-0000-0000-000000000005', 'A', 'Packed red cells, fresh frozen plasma, and platelets in a ratio of approximately 1:1:1', true, 'Correct. Major haemorrhage protocols use an empirical fixed ratio of approximately 1:1:1 red cells to FFP to platelets early on, before laboratory-guided targets become available, to reduce trauma-induced coagulopathy.', 1),
('c4000000-0000-0000-0000-000000000005', 'B', 'Packed red cells alone, with plasma and platelets given only once all red cells have been transfused', false, 'Ruled out because delaying plasma and platelets behind red cells worsens dilutional coagulopathy.', 2),
('c4000000-0000-0000-0000-000000000005', 'C', 'Packed red cells and platelets only, omitting fresh frozen plasma', false, 'Ruled out because omitting FFP fails to replace clotting factors and worsens coagulopathy.', 3),
('c4000000-0000-0000-0000-000000000005', 'D', 'Four units of packed red cells to one unit of fresh frozen plasma', false, 'Ruled out because this red-cell-predominant ratio under-replaces clotting factors compared with the recommended balanced approach.', 4),
('c4000000-0000-0000-0000-000000000005', 'E', 'Crystalloid should make up the majority of volume replacement, with blood products reserved for haemoglobin below 70 g/L', false, 'Ruled out because this contradicts major haemorrhage protocol principles, which minimise crystalloid in favour of early balanced blood products.', 5),
('c4000000-0000-0000-0000-000000000006', 'A', 'Simple rib fracture; reassure and discharge with analgesia', false, 'Ruled out because paradoxical chest wall movement indicates a flail segment, which carries a higher risk of respiratory compromise and needs monitoring, not discharge.', 1),
('c4000000-0000-0000-0000-000000000006', 'B', 'Tension pneumothorax; perform immediate needle decompression', false, 'Ruled out because there is no tracheal deviation, absent breath sounds, or haemodynamic collapse described, which would be expected in tension pneumothorax.', 2),
('c4000000-0000-0000-0000-000000000006', 'C', 'Flail chest with underlying pulmonary contusion; priorities are oxygenation, analgesia, and close monitoring for respiratory deterioration', true, 'Correct. Paradoxical chest wall movement from segmental multiple rib fractures defines a flail segment, commonly with underlying pulmonary contusion; the main risks are hypoventilation and progressive respiratory failure.', 3),
('c4000000-0000-0000-0000-000000000006', 'D', 'Cardiac tamponade; arrange urgent pericardiocentesis', false, 'Ruled out because there are no muffled heart sounds or distended neck veins described to support tamponade.', 4),
('c4000000-0000-0000-0000-000000000006', 'E', 'Diaphragmatic rupture; arrange urgent laparotomy', false, 'Ruled out because the findings described (paradoxical chest wall movement with multiple rib fractures) are characteristic of flail chest, not diaphragmatic rupture.', 5),
('c4000000-0000-0000-0000-000000000007', 'A', 'Aggressive intravenous crystalloid alone with observation', false, 'Ruled out because fluids alone do not relieve the pericardial pressure causing obstructive shock in tamponade.', 1),
('c4000000-0000-0000-0000-000000000007', 'B', 'Needle decompression of the chest for presumed tension pneumothorax', false, 'Ruled out because the findings (muffled heart sounds, pericardial fluid on FAST) indicate tamponade rather than a pneumothorax.', 2),
('c4000000-0000-0000-0000-000000000007', 'C', 'Discharge with outpatient cardiology review', false, 'Ruled out because cardiac tamponade from penetrating trauma is immediately life-threatening.', 3),
('c4000000-0000-0000-0000-000000000007', 'D', 'Give diuretics to reduce cardiac preload', false, 'Ruled out because tamponade physiology is preload-dependent, and reducing preload can precipitate cardiovascular collapse.', 4),
('c4000000-0000-0000-0000-000000000007', 'E', 'Urgent pericardial decompression and immediate surgical referral for definitive repair', true, $x$Correct. Beck's triad with pericardial fluid on FAST after penetrating chest trauma indicates cardiac tamponade, a life-threatening obstructive shock requiring urgent decompression and definitive surgical control of the underlying injury.$x$, 5),
('c4000000-0000-0000-0000-000000000008', 'A', 'Urgent CT head within 1 hour', true, 'Correct. Anticoagulant therapy in a patient with head injury is an indication for CT head within 1 hour under NICE guidance, regardless of a normal GCS.', 1),
('c4000000-0000-0000-0000-000000000008', 'B', 'Discharge home with a head injury advice leaflet and safety-netting', false, 'Ruled out because anticoagulation with head injury requires CT even when GCS is 15.', 2),
('c4000000-0000-0000-0000-000000000008', 'C', 'Observe on the ward for 24 hours without imaging', false, 'Ruled out because delaying imaging in an anticoagulated patient with head injury increases the risk of a missed intracranial bleed.', 3),
('c4000000-0000-0000-0000-000000000008', 'D', 'Reverse warfarin with vitamin K only, with no imaging required', false, 'Ruled out because imaging is still required to establish whether a bleed is present, regardless of reversal.', 4),
('c4000000-0000-0000-0000-000000000008', 'E', 'Arrange MRI head as the first-line investigation', false, 'Ruled out because CT, not MRI, is the first-line investigation for suspected acute traumatic intracranial injury.', 5),
('c4000000-0000-0000-0000-000000000009', 'A', 'Await urine culture results before starting antibiotics', false, 'Ruled out because antibiotics should not be delayed pending microbiology results in suspected sepsis.', 1),
('c4000000-0000-0000-0000-000000000009', 'B', 'Give oral antibiotics with outpatient follow-up', false, 'Ruled out because he has organ dysfunction (confusion, hypotension, raised lactate), needing urgent IV treatment, not oral outpatient management.', 2),
('c4000000-0000-0000-0000-000000000009', 'C', 'Arrange CT abdomen/pelvis before starting any treatment', false, 'Ruled out because resuscitation and antibiotics take priority; imaging should not delay treatment.', 3),
('c4000000-0000-0000-0000-000000000009', 'D', 'Give high-flow oxygen, take blood cultures, measure lactate and urine output, give IV fluids, and start empirical broad-spectrum IV antibiotics within one hour', true, $x$Correct. Suspected sepsis with organ dysfunction (confusion, hypotension, raised lactate) requires the 'Sepsis Six' bundle delivered within one hour.$x$, 4),
('c4000000-0000-0000-0000-000000000009', 'E', 'Give antipyretics only and reassess in 4 hours', false, 'Ruled out because this is insufficient for sepsis with evidence of organ dysfunction.', 5),
('c4000000-0000-0000-0000-000000000010', 'A', 'Give a further 30 mL/kg crystalloid bolus and reassess in an hour on the ward', false, 'Ruled out because ongoing hypotension despite adequate fluid resuscitation defines septic shock requiring vasopressor support, not further fluid alone on a general ward.', 1),
('c4000000-0000-0000-0000-000000000010', 'B', 'Urgent escalation to critical care for consideration of vasopressor support, as this is septic shock refractory to fluid resuscitation', true, 'Correct. Persisting hypotension and raised lactate despite adequate fluid resuscitation defines septic shock, requiring vasopressor support and invasive monitoring, which needs urgent critical care escalation.', 2),
('c4000000-0000-0000-0000-000000000010', 'C', 'Start an oral antihypertensive medication', false, 'Ruled out because the patient is hypotensive, not hypertensive.', 3),
('c4000000-0000-0000-0000-000000000010', 'D', 'Discharge for outpatient follow-up once her temperature settles', false, 'Ruled out because she is haemodynamically unstable with septic shock.', 4),
('c4000000-0000-0000-0000-000000000010', 'E', 'Give furosemide to offload fluid', false, 'Ruled out because diuretics would worsen hypotension in a shocked patient.', 5),
('c4000000-0000-0000-0000-000000000011', 'A', 'Intravenous antihistamine alone as first-line treatment', false, 'Ruled out because IM adrenaline, not antihistamines, is first-line for anaphylaxis.', 1),
('c4000000-0000-0000-0000-000000000011', 'B', 'IV hydrocortisone alone, with adrenaline reserved if she deteriorates further', false, 'Ruled out because adrenaline should be given immediately, not held back until deterioration.', 2),
('c4000000-0000-0000-0000-000000000011', 'C', 'Nebulised salbutamol only, with no adrenaline required', false, 'Ruled out because this does not treat the systemic anaphylactic reaction; adrenaline is essential.', 3),
('c4000000-0000-0000-0000-000000000011', 'D', 'Intramuscular adrenaline 500 micrograms, high-flow oxygen, and call for senior/resuscitation help', true, 'Correct. Intramuscular adrenaline is the first-line treatment for anaphylaxis and should be given immediately alongside oxygen and a call for help, without waiting for other treatments.', 4),
('c4000000-0000-0000-0000-000000000011', 'E', 'Oral antihistamine and observation in the waiting room', false, 'Ruled out because this is inappropriate for a life-threatening anaphylactic reaction with airway and circulatory compromise.', 5),
('c4000000-0000-0000-0000-000000000012', 'A', 'Hypovolaemic shock; give rapid large-volume IV fluids', false, 'Ruled out because the raised JVP and pulmonary oedema indicate fluid overload rather than hypovolaemia, and aggressive fluids would worsen pulmonary oedema.', 1),
('c4000000-0000-0000-0000-000000000012', 'B', 'Cardiogenic shock secondary to extensive myocardial damage; urgent echocardiography and discussion with cardiology/critical care regarding inotropic support', true, 'Correct. Hypotension with poor perfusion and pulmonary oedema following extensive MI indicates cardiogenic shock, requiring specialist input for inotropic support and consideration of mechanical circulatory support.', 2),
('c4000000-0000-0000-0000-000000000012', 'C', 'Anaphylaxis; give intramuscular adrenaline', false, 'Ruled out because there is no allergic trigger or urticaria described; the picture fits cardiogenic shock.', 3),
('c4000000-0000-0000-0000-000000000012', 'D', 'Discharge with outpatient cardiology follow-up', false, 'Ruled out because he is haemodynamically unstable.', 4),
('c4000000-0000-0000-0000-000000000012', 'E', 'Reassure and observe, as post-PCI hypotension is expected and self-limiting', false, 'Ruled out because this presentation of shock with pulmonary oedema needs urgent action, not reassurance.', 5),
('c4000000-0000-0000-0000-000000000013', 'A', 'Haemorrhagic shock from unidentified internal bleeding', false, 'Ruled out because haemorrhagic shock typically causes tachycardia and cool peripheries from compensatory vasoconstriction, not bradycardia with warm peripheries.', 1),
('c4000000-0000-0000-0000-000000000013', 'B', 'Cardiogenic shock from myocardial contusion', false, 'Ruled out because this would typically present with poor perfusion and cool peripheries, and does not explain bradycardia with warm peripheries as well as cord injury does.', 2),
('c4000000-0000-0000-0000-000000000013', 'C', 'Neurogenic shock due to loss of sympathetic tone below the level of spinal cord injury', true, 'Correct. Loss of sympathetic vascular tone below a spinal cord injury causes vasodilation and unopposed vagal tone, producing hypotension with bradycardia and warm peripheries.', 3),
('c4000000-0000-0000-0000-000000000013', 'D', 'Septic shock from an occult infection', false, 'Ruled out because there is no fever or infective source, and the timeframe immediately after trauma does not fit.', 4),
('c4000000-0000-0000-0000-000000000013', 'E', 'Tension pneumothorax', false, 'Ruled out because this would present with respiratory distress and tracheal deviation, not warm peripheries with bradycardia.', 5),
('c4000000-0000-0000-0000-000000000014', 'A', 'Await the haemoglobin result before transfusing', false, 'Ruled out because clinical evidence of shock should prompt transfusion without waiting for a repeat laboratory result.', 1),
('c4000000-0000-0000-0000-000000000014', 'B', 'Perform immediate endoscopy before any resuscitation', false, 'Ruled out because resuscitation (airway, breathing, circulation) takes priority over endoscopy in an unstable upper GI bleed.', 2),
('c4000000-0000-0000-0000-000000000014', 'C', 'Start oral iron replacement', false, 'Ruled out because this is inadequate for an acute, massive bleed.', 3),
('c4000000-0000-0000-0000-000000000014', 'D', 'Discharge with outpatient gastroenterology follow-up', false, 'Ruled out because he is haemodynamically unstable and requires immediate admission and resuscitation.', 4),
('c4000000-0000-0000-0000-000000000014', 'E', 'Two large-bore IV cannulae, urgent blood transfusion, IV terlipressin and prophylactic antibiotics, with endoscopy once resuscitated', true, 'Correct. In suspected variceal haemorrhage, terlipressin and prophylactic antibiotics should be started alongside resuscitation and transfusion, before endoscopy.', 5),
('c4000000-0000-0000-0000-000000000015', 'A', 'Toxic shock syndrome; remove the tampon, take blood cultures, and start IV fluids and empirical broad-spectrum antibiotics urgently', true, 'Correct. Toxic shock syndrome should be considered in a young woman with fever, rash, hypotension, and multi-organ involvement with tampon use; removing the foreign material is an urgent source-control step alongside sepsis-type resuscitation.', 1),
('c4000000-0000-0000-0000-000000000015', 'B', 'Simple viral gastroenteritis; manage with oral rehydration at home', false, 'Ruled out because the combination of shock, rash, and fever indicates a severe systemic illness, not simple gastroenteritis.', 2),
('c4000000-0000-0000-0000-000000000015', 'C', 'Anaphylaxis; give intramuscular adrenaline', false, 'Ruled out because there is no allergen exposure, urticaria, or angioedema described; the picture fits toxic shock syndrome.', 3),
('c4000000-0000-0000-0000-000000000015', 'D', 'Discharge with antiemetics only', false, 'Ruled out because she is haemodynamically unstable.', 4),
('c4000000-0000-0000-0000-000000000015', 'E', 'Wait for menstruation to end before any intervention', false, 'Ruled out because the tampon should be removed immediately as part of urgent source control.', 5),
('c4000000-0000-0000-0000-000000000016', 'A', 'Await formal confirmation of neutropenia from a repeat blood count before starting antibiotics', false, 'Ruled out because treatment should not be delayed in suspected neutropenic sepsis.', 1),
('c4000000-0000-0000-0000-000000000016', 'B', 'Give oral antibiotics as an outpatient with review in 48 hours', false, 'Ruled out because neutropenic sepsis requires urgent IV antibiotics and admission, not outpatient management.', 2),
('c4000000-0000-0000-0000-000000000016', 'C', 'Withhold antibiotics until a clear source of infection is identified', false, 'Ruled out because empirical treatment should not wait for source identification.', 3),
('c4000000-0000-0000-0000-000000000016', 'D', 'Treat as neutropenic sepsis and give empirical broad-spectrum IV antibiotics within 1 hour of arrival', true, 'Correct. Neutropenic sepsis is a medical emergency in any patient on chemotherapy presenting with fever; empirical broad-spectrum IV antibiotics must be given within 1 hour.', 4),
('c4000000-0000-0000-0000-000000000016', 'E', 'Give granulocyte colony-stimulating factor (G-CSF) alone without antibiotics', false, 'Ruled out because G-CSF is an adjunct in some cases but does not replace the priority of urgent empirical antibiotics.', 5),
('c4000000-0000-0000-0000-000000000017', 'A', 'Start intravenous acetylcysteine (NAC)', true, 'Correct. A plasma paracetamol level above the treatment line on the nomogram, following a single acute ingestion presenting between 4-24 hours, is an indication for acetylcysteine.', 1),
('c4000000-0000-0000-0000-000000000017', 'B', 'Give activated charcoal only, with no NAC required as she is currently asymptomatic', false, 'Ruled out because NAC is indicated based on the nomogram level, independent of symptoms, and charcoal alone does not treat a level above the treatment line.', 2),
('c4000000-0000-0000-0000-000000000017', 'C', 'Discharge with outpatient liver function test follow-up', false, 'Ruled out because a level above the treatment line requires immediate treatment, not outpatient monitoring.', 3),
('c4000000-0000-0000-0000-000000000017', 'D', 'Withhold treatment until liver function tests become abnormal', false, 'Ruled out because NAC is most effective when started early, before organ damage develops, and should not be delayed.', 4),
('c4000000-0000-0000-0000-000000000017', 'E', 'Gastric lavage as the definitive treatment', false, 'Ruled out because gastric lavage is not standard practice and does not replace the need for NAC.', 5),
('c4000000-0000-0000-0000-000000000018', 'A', 'Perform immediate rapid sequence intubation without a trial of naloxone', false, 'Ruled out because naloxone often rapidly reverses opioid-induced respiratory depression and should be given alongside airway support before proceeding to intubation.', 1),
('c4000000-0000-0000-0000-000000000018', 'B', 'Give flumazenil', false, 'Ruled out because flumazenil is the reversal agent for benzodiazepines, not opioids; the pinpoint pupils and history fit opioid toxicity.', 2),
('c4000000-0000-0000-0000-000000000018', 'C', 'Give activated charcoal', false, 'Ruled out because this does not address the immediate respiratory depression in an obtunded patient with an unprotected airway.', 3),
('c4000000-0000-0000-0000-000000000018', 'D', 'Observe only, with no treatment required', false, 'Ruled out because he is hypoxic with significant respiratory depression, requiring immediate treatment.', 4),
('c4000000-0000-0000-0000-000000000018', 'E', 'Give IV/IM naloxone, supporting his airway and ventilation with bag-valve-mask as needed', true, 'Correct. The triad of respiratory depression, pinpoint pupils, and reduced consciousness suggests opioid toxicity; naloxone is the specific reversal agent and should be given promptly while supporting ventilation.', 5),
('c4000000-0000-0000-0000-000000000019', 'A', 'Give flumazenil routinely to reverse sedation', false, 'Ruled out because in chronic benzodiazepine users, flumazenil risks precipitating withdrawal seizures and is reserved for specific situations under specialist guidance.', 1),
('c4000000-0000-0000-0000-000000000019', 'B', 'Give naloxone', false, 'Ruled out because naloxone reverses opioids, not benzodiazepines.', 2),
('c4000000-0000-0000-0000-000000000019', 'C', 'Supportive care with airway monitoring and observation; flumazenil should be avoided given her chronic benzodiazepine use', true, 'Correct. In chronic benzodiazepine users, flumazenil can precipitate withdrawal seizures, so most overdoses are managed supportively with close monitoring rather than reversal.', 3),
('c4000000-0000-0000-0000-000000000019', 'D', 'Perform immediate intubation without a trial of supportive measures', false, 'Ruled out because this is not immediately necessary at this GCS and respiratory rate unless she deteriorates further.', 4),
('c4000000-0000-0000-0000-000000000019', 'E', 'Discharge home once she is rousable, with no further monitoring required', false, 'Ruled out because she requires a period of observation for the risk of re-sedation.', 5),
('c4000000-0000-0000-0000-000000000020', 'A', 'Intravenous flecainide to control the widened QRS', false, 'Ruled out because flecainide is itself a sodium channel blocker and would worsen the toxicity.', 1),
('c4000000-0000-0000-0000-000000000020', 'B', 'Intravenous sodium bicarbonate', true, 'Correct. Tricyclic antidepressant overdose causes sodium channel blockade; IV sodium bicarbonate is the specific treatment for the resulting QRS widening and reduces the risk of ventricular arrhythmia.', 2),
('c4000000-0000-0000-0000-000000000020', 'C', 'Intravenous calcium gluconate', false, 'Ruled out because this is the treatment for calcium channel blocker toxicity or hyperkalaemia, not the primary treatment for tricyclic-induced QRS widening.', 3),
('c4000000-0000-0000-0000-000000000020', 'D', 'A beta-blocker to slow the heart rate', false, 'Ruled out because beta-blockade can worsen hypotension and cardiotoxicity in tricyclic overdose.', 4),
('c4000000-0000-0000-0000-000000000020', 'E', 'Activated charcoal alone as the only treatment required', false, 'Ruled out because charcoal may be considered if within 1 hour of ingestion, but it does not treat established cardiotoxicity; bicarbonate is needed for the ECG change.', 5),
('c4000000-0000-0000-0000-000000000021', 'A', 'Intravenous sodium bicarbonate to correct his respiratory alkalosis', false, 'Ruled out because the purpose of bicarbonate here is to alkalinise the urine for salicylate elimination, not to correct the primary respiratory alkalosis.', 1),
('c4000000-0000-0000-0000-000000000021', 'B', 'Haemodialysis as first-line treatment for all salicylate overdoses', false, 'Ruled out because haemodialysis is reserved for severe toxicity (very high levels, renal failure, refractory acidosis, pulmonary oedema, or significant CNS effects), not for moderate levels.', 2),
('c4000000-0000-0000-0000-000000000021', 'C', 'Activated charcoal has no role and should not be considered', false, 'Ruled out because activated charcoal can be considered, particularly with large ingestions or if within 1 hour of ingestion.', 3),
('c4000000-0000-0000-0000-000000000021', 'D', 'Intravenous sodium bicarbonate to alkalinise the urine and enhance salicylate elimination, alongside IV fluids', true, 'Correct. Urinary alkalinisation with IV sodium bicarbonate enhances renal elimination of salicylate by ion-trapping it in its ionised form in alkaline urine.', 4),
('c4000000-0000-0000-0000-000000000021', 'E', 'Intravenous insulin and dextrose', false, 'Ruled out because this is used for other overdoses/hyperkalaemia, not the mechanism for enhancing salicylate elimination.', 5),
('c4000000-0000-0000-0000-000000000022', 'A', 'Room air only, as their symptoms are mild', false, 'Ruled out because high-flow oxygen should be given regardless of symptom severity, as it accelerates carbon monoxide elimination.', 1),
('c4000000-0000-0000-0000-000000000022', 'B', 'High-flow 100% oxygen via a non-rebreathe mask for all affected individuals, with a lower threshold for discussing hyperbaric oxygen for the pregnant woman', true, 'Correct. High-flow 100% oxygen accelerates dissociation of carbon monoxide from haemoglobin; a lower threshold for hyperbaric oxygen applies in pregnancy because fetal haemoglobin has a higher affinity for carbon monoxide.', 2),
('c4000000-0000-0000-0000-000000000022', 'C', 'Discharge once the headache resolves, with no monitoring of carboxyhaemoglobin trend', false, 'Ruled out because ongoing monitoring and appropriate treatment are needed, particularly given the fetal risk in the pregnant patient.', 3),
('c4000000-0000-0000-0000-000000000022', 'D', 'Blood transfusion to replace carboxyhaemoglobin-bound red cells', false, 'Ruled out because oxygen displaces carbon monoxide from existing haemoglobin; transfusion is not the treatment.', 4),
('c4000000-0000-0000-0000-000000000022', 'E', 'Naloxone', false, 'Ruled out because naloxone has no role in carbon monoxide poisoning.', 5),
('c4000000-0000-0000-0000-000000000023', 'A', 'Fomepizole (or ethanol if fomepizole is unavailable)', true, 'Correct. Visual disturbance with a high anion gap metabolic acidosis and raised osmolar gap after ingesting illicit alcohol suggests methanol poisoning; fomepizole (or ethanol) inhibits alcohol dehydrogenase, preventing formation of the toxic metabolite formic acid.', 1),
('c4000000-0000-0000-0000-000000000023', 'B', 'Naloxone', false, 'Ruled out because this is not opioid toxicity.', 2),
('c4000000-0000-0000-0000-000000000023', 'C', 'N-acetylcysteine', false, 'Ruled out because this is the antidote for paracetamol overdose, not toxic alcohol poisoning.', 3),
('c4000000-0000-0000-0000-000000000023', 'D', 'Flumazenil', false, 'Ruled out because this is the antidote for benzodiazepines, not toxic alcohols.', 4),
('c4000000-0000-0000-0000-000000000023', 'E', 'Activated charcoal as the definitive treatment', false, 'Ruled out because alcohols are poorly adsorbed by activated charcoal and this is not the definitive treatment here.', 5),
('c4000000-0000-0000-0000-000000000024', 'A', 'Activated charcoal', false, 'Ruled out because iron is not adsorbed by activated charcoal.', 1),
('c4000000-0000-0000-0000-000000000024', 'B', 'N-acetylcysteine', false, 'Ruled out because this is the antidote for paracetamol, not iron.', 2),
('c4000000-0000-0000-0000-000000000024', 'C', 'Whole bowel irrigation is contraindicated in iron overdose', false, 'Ruled out because whole bowel irrigation may actually be considered for large iron tablet ingestions to reduce ongoing absorption, so this statement is false.', 3),
('c4000000-0000-0000-0000-000000000024', 'D', 'Supportive care alone with no chelation therapy', false, 'Ruled out because significant toxicity with systemic symptoms and a markedly elevated level warrants desferrioxamine.', 4),
('c4000000-0000-0000-0000-000000000024', 'E', 'Intravenous desferrioxamine (deferoxamine)', true, 'Correct. Desferrioxamine is the specific chelating agent for significant iron toxicity, indicated with systemic symptoms and markedly elevated serum iron levels.', 5),
('c4000000-0000-0000-0000-000000000025', 'A', 'Intravenous adenosine', false, 'Ruled out because adenosine is used for supraventricular tachycardia and could worsen bradycardia or heart block in this context.', 1),
('c4000000-0000-0000-0000-000000000025', 'B', 'Intravenous digoxin', false, 'Ruled out because digoxin has no role in beta-blocker overdose management and risks additional toxicity.', 2),
('c4000000-0000-0000-0000-000000000025', 'C', 'Intravenous glucagon', true, 'Correct. Glucagon increases intracellular cAMP independent of the blocked beta-receptor, making it a key treatment for beta-blocker overdose with refractory bradycardia and hypotension.', 3),
('c4000000-0000-0000-0000-000000000025', 'D', 'Intravenous naloxone', false, 'Ruled out because naloxone has no role in beta-blocker toxicity.', 4),
('c4000000-0000-0000-0000-000000000025', 'E', 'Immediate synchronised cardioversion', false, 'Ruled out because this is not a tachyarrhythmia requiring cardioversion; the patient is bradycardic.', 5),
('c4000000-0000-0000-0000-000000000026', 'A', 'IV insulin to correct his blood glucose', false, 'Ruled out because he is hypoglycaemic; insulin would worsen this.', 1),
('c4000000-0000-0000-0000-000000000026', 'B', 'Withhold treatment and await a formal laboratory glucose result', false, 'Ruled out because a symptomatic patient with a low capillary glucose should be treated immediately.', 2),
('c4000000-0000-0000-0000-000000000026', 'C', 'IV 10% dextrose (or IM glucagon if no IV access), then recheck glucose and give longer-acting carbohydrate once he can safely swallow', true, 'Correct. Severe symptomatic hypoglycaemia in a patient who cannot safely take oral carbohydrate requires IV dextrose or IM glucagon, followed by longer-acting carbohydrate to prevent rebound hypoglycaemia.', 3),
('c4000000-0000-0000-0000-000000000026', 'D', 'Oral glucose gel only, despite his reduced GCS making swallowing unsafe', false, 'Ruled out because of the aspiration risk; the IV or IM route is needed while GCS is impaired.', 4),
('c4000000-0000-0000-0000-000000000026', 'E', 'A 0.9% saline bolus alone', false, 'Ruled out because saline does not treat hypoglycaemia directly.', 5),
('c4000000-0000-0000-0000-000000000027', 'A', 'Immediate rapid sequence induction and intubation without trying benzodiazepines first', false, 'Ruled out because first-line treatment is benzodiazepines; intubation is reserved for refractory status or airway compromise.', 1),
('c4000000-0000-0000-0000-000000000027', 'B', 'Oral diazepam', false, 'Ruled out because the IV route is required for prompt effect during an ongoing seizure, especially with IV access already available.', 2),
('c4000000-0000-0000-0000-000000000027', 'C', 'Observation only, as seizures are usually self-limiting', false, 'Ruled out because a seizure lasting over 5 minutes is defined as status epilepticus and requires active treatment.', 3),
('c4000000-0000-0000-0000-000000000027', 'D', 'IV lorazepam, with a repeat dose if the seizure continues, escalating to a second-line agent if it persists', true, 'Correct. Status epilepticus (seizure lasting over 5 minutes) requires first-line IV benzodiazepine treatment, escalating to second-line agents if seizures persist.', 4),
('c4000000-0000-0000-0000-000000000027', 'E', 'IV magnesium sulfate as first-line treatment', false, 'Ruled out because this is used for eclamptic seizures in pregnancy, not standard status epilepticus management.', 5),
('c4000000-0000-0000-0000-000000000028', 'A', 'Place him in the recovery position, ensure his airway is maintained, and monitor closely while he recovers', true, 'Correct. A brief period of confusion and drowsiness (post-ictal state) is expected after a generalised seizure; management focuses on airway protection, safety, and monitoring during natural recovery.', 1),
('c4000000-0000-0000-0000-000000000028', 'B', 'Give IV lorazepam immediately for ongoing status epilepticus', false, 'Ruled out because the seizure has already terminated; this is a normal post-ictal state, not ongoing status epilepticus.', 2),
('c4000000-0000-0000-0000-000000000028', 'C', 'Perform an immediate CT head before any period of observation', false, 'Ruled out because this is not required for a typical seizure with known epilepsy and an expected post-ictal recovery, absent atypical features.', 3),
('c4000000-0000-0000-0000-000000000028', 'D', 'Restrain him firmly to prevent movement during recovery', false, 'Ruled out because this is inappropriate and may cause harm.', 4),
('c4000000-0000-0000-0000-000000000028', 'E', 'Discharge immediately once seizure activity stops, with no observation period', false, 'Ruled out because patients need a period of monitoring during post-ictal recovery before safe discharge.', 5),
('c4000000-0000-0000-0000-000000000029', 'A', 'Epileptic seizure unrelated to alcohol; start long-term antiepileptic medication only', false, 'Ruled out because the timing and autonomic features strongly suggest withdrawal, and long-term antiepileptics are not the first management step.', 1),
('c4000000-0000-0000-0000-000000000029', 'B', 'Hypoglycaemia; give IV dextrose only, with no benzodiazepine required', false, 'Ruled out because the classic timeline and autonomic features point to alcohol withdrawal rather than hypoglycaemia alone, and dextrose alone does not address withdrawal.', 2),
('c4000000-0000-0000-0000-000000000029', 'C', 'Discharge to allow him to detox at home', false, 'Ruled out because an alcohol withdrawal seizure raises concern for progression to delirium tremens, warranting inpatient management.', 3),
('c4000000-0000-0000-0000-000000000029', 'D', 'Immediate disulfiram administration', false, 'Ruled out because disulfiram is used for relapse prevention during abstinence, not acute withdrawal seizure management, and can be dangerous if alcohol remains in the system.', 4),
('c4000000-0000-0000-0000-000000000029', 'E', 'Alcohol withdrawal seizure; treat the acute seizure as needed and start a reducing benzodiazepine regimen with thiamine', true, $x$Correct. The timing and preceding autonomic hyperactivity (tremor, tachycardia, hypertension, sweating) suggest an alcohol withdrawal seizure, managed with a reducing benzodiazepine regimen and thiamine to prevent Wernicke's encephalopathy.$x$, 5),
('c4000000-0000-0000-0000-000000000030', 'A', 'Immediate liver transplant referral as the only appropriate action', false, 'Ruled out because transplant referral is not the immediate step; the acute precipitant and complications should be managed first.', 1),
('c4000000-0000-0000-0000-000000000030', 'B', 'Treat as hepatic encephalopathy; give lactulose to reduce ammonia absorption and screen for other precipitants such as infection or GI bleeding', true, 'Correct. Confusion with asterixis in known liver disease suggests hepatic encephalopathy; constipation is a common precipitant, and lactulose is first-line treatment alongside screening for other precipitants.', 2),
('c4000000-0000-0000-0000-000000000030', 'C', 'IV naloxone', false, 'Ruled out because there is no evidence of opioid use; the asterixis and cirrhosis history point to hepatic encephalopathy.', 3),
('c4000000-0000-0000-0000-000000000030', 'D', 'Restrict all fluids and give diuretics only', false, 'Ruled out because this does not address hepatic encephalopathy management.', 4),
('c4000000-0000-0000-0000-000000000030', 'E', 'Discharge with outpatient hepatology follow-up', false, 'Ruled out because this is unsafe given his reduced GCS; he needs admission and treatment.', 5),
('c4000000-0000-0000-0000-000000000031', 'A', 'Discharge with simple analgesia, as the CT is normal', false, 'Ruled out because CT sensitivity decreases with time since onset, so a normal scan performed later does not exclude subarachnoid haemorrhage.', 1),
('c4000000-0000-0000-0000-000000000031', 'B', 'Repeat CT head immediately as the only further investigation needed', false, 'Ruled out because repeat CT adds little once the initial CT is normal; lumbar puncture is the appropriate next step.', 2),
('c4000000-0000-0000-0000-000000000031', 'C', 'MRI brain as the definitive test to exclude subarachnoid haemorrhage', false, 'Ruled out because lumbar puncture for xanthochromia (or CT angiography if strongly suspected) is the standard next step, not routine MRI.', 3),
('c4000000-0000-0000-0000-000000000031', 'D', 'Lumbar puncture, now more than 12 hours after symptom onset, looking for xanthochromia', true, 'Correct. CT sensitivity for subarachnoid haemorrhage decreases with time since onset, so a normal CT performed outside the highest-sensitivity early window does not reliably exclude it; lumbar puncture for xanthochromia at least 12 hours after onset is the appropriate next step.', 4),
('c4000000-0000-0000-0000-000000000031', 'E', 'Treat as migraine and discharge with triptans', false, 'Ruled out because a thunderclap headache needs to be worked up for subarachnoid haemorrhage before being diagnosed as migraine.', 5),
('c4000000-0000-0000-0000-000000000032', 'A', 'A generalised tonic-clonic epileptic seizure', false, 'Ruled out because typical epileptic seizures usually have open eyes and stereotyped tonic-then-clonic activity, followed by post-ictal confusion, unlike this presentation.', 1),
('c4000000-0000-0000-0000-000000000032', 'B', 'A psychogenic non-epileptic (dissociative) seizure', true, 'Correct. Closed eyes during the event, waxing-and-waning activity, prolonged duration, pelvic thrusting, and immediate return to normal awareness without post-ictal confusion are features more typical of a non-epileptic attack than a true epileptic seizure.', 2),
('c4000000-0000-0000-0000-000000000032', 'C', 'An absence seizure', false, 'Ruled out because absence seizures are brief (seconds), with no prolonged convulsive motor activity.', 3),
('c4000000-0000-0000-0000-000000000032', 'D', 'Cardiac syncope', false, 'Ruled out because syncope is usually brief with rapid recovery, not prolonged limb shaking of this pattern.', 4),
('c4000000-0000-0000-0000-000000000032', 'E', 'A hypoglycaemic seizure', false, 'Ruled out because glucose is stated as normal, excluding this.', 5),
('c4000000-0000-0000-0000-000000000033', 'A', 'Rapid correction with large volumes of hypertonic saline to normalise sodium as quickly as possible', false, 'Ruled out because overly rapid correction of hyponatraemia risks osmotic demyelination syndrome.', 1),
('c4000000-0000-0000-0000-000000000033', 'B', 'Fluid restriction alone as the acute treatment for a seizure', false, 'Ruled out because fluid restriction is a longer-term measure for some causes of hyponatraemia, not the acute treatment of a seizure caused by severe hyponatraemia.', 2),
('c4000000-0000-0000-0000-000000000033', 'C', 'Urgent involvement of senior/critical care and consideration of small-volume hypertonic saline, with careful correction to avoid overly rapid correction', true, 'Correct. Severe symptomatic hyponatraemia with seizure is a medical emergency requiring urgent correction with small-volume hypertonic saline under senior guidance, while avoiding overly rapid correction.', 3),
('c4000000-0000-0000-0000-000000000033', 'D', 'IV dextrose 5%', false, 'Ruled out because hypotonic/dextrose fluids can worsen hyponatraemia.', 4),
('c4000000-0000-0000-0000-000000000033', 'E', 'Discharge with outpatient monitoring of sodium levels', false, 'Ruled out because this is unsafe given the seizure and severe hyponatraemia; admission is required.', 5),
('c4000000-0000-0000-0000-000000000034', 'A', 'Await lumbar puncture results before starting any antibiotics', false, 'Ruled out because antibiotics should not be delayed for lumbar puncture in suspected bacterial meningitis.', 1),
('c4000000-0000-0000-0000-000000000034', 'B', 'Perform a CT head first, giving antibiotics only if it shows raised intracranial pressure', false, 'Ruled out because CT should not delay antibiotics; the lumbar puncture may be deferred if contraindicated, but antibiotics are given immediately regardless.', 2),
('c4000000-0000-0000-0000-000000000034', 'C', 'Give oral antibiotics as an outpatient with review in 24 hours', false, 'Ruled out because this is a medical emergency requiring immediate IV antibiotics and admission.', 3),
('c4000000-0000-0000-0000-000000000034', 'D', 'Give dexamethasone alone, with antibiotics deferred until microbiology confirms the organism', false, 'Ruled out because empirical antibiotics should be started immediately; steroids are an adjunct, not a substitute.', 4),
('c4000000-0000-0000-0000-000000000034', 'E', 'Give IV broad-spectrum antibiotics immediately, without waiting for lumbar puncture or CT', true, 'Correct. Suspected bacterial meningitis with a non-blanching rash suggesting meningococcal disease requires immediate empirical IV antibiotics without waiting for further investigations.', 5),
('c4000000-0000-0000-0000-000000000035', 'A', 'High-flow oxygen with back-to-back nebulised salbutamol and ipratropium bromide, plus oral or IV corticosteroids', true, 'Correct. Acute severe asthma (inability to complete sentences, RR >25, HR >110, PEF 33-50% predicted) requires oxygen, repeated nebulised short-acting beta-agonist and anticholinergic bronchodilators, and early systemic corticosteroids.', 1),
('c4000000-0000-0000-0000-000000000035', 'B', 'Discharge with a course of oral antibiotics for a presumed chest infection', false, 'Ruled out because there is no evidence of infection described, and this is an acute severe asthma exacerbation requiring immediate bronchodilator and steroid treatment, not antibiotics or discharge.', 2),
('c4000000-0000-0000-0000-000000000035', 'C', 'Reassure and advise increasing the frequency of her regular inhaled corticosteroid at home', false, 'Ruled out because acute severe asthma with these features needs emergency treatment in hospital, not a change to her maintenance regimen managed at home.', 3),
('c4000000-0000-0000-0000-000000000035', 'D', 'Intubate and ventilate immediately, before a trial of nebulised bronchodilators', false, 'Ruled out because intubation is reserved for life-threatening or near-fatal features (silent chest, exhaustion, coma, respiratory arrest); this patient should first be treated with nebulised bronchodilators and steroids.', 4),
('c4000000-0000-0000-0000-000000000035', 'E', 'Give a single dose of nebulised salbutamol only and discharge if she feels subjectively better', false, 'Ruled out because acute severe asthma needs repeated/back-to-back nebulisers, steroids, and objective reassessment of PEF before any discharge decision.', 5),
('c4000000-0000-0000-0000-000000000036', 'A', 'Subcutaneous rapid-acting insulin alone, with no IV fluids required', false, 'Ruled out because DKA management requires IV fluid resuscitation alongside insulin; subcutaneous insulin has unreliable absorption in a dehydrated, acidotic patient.', 1),
('c4000000-0000-0000-0000-000000000036', 'B', 'Withhold insulin until the serum potassium result is available', false, 'Ruled out because fluid resuscitation should begin immediately, and insulin should not be delayed for long once potassium is known to be safe to start (or is being monitored), but the priority is not indefinite withholding while fluids are also delayed.', 2),
('c4000000-0000-0000-0000-000000000036', 'C', 'IV 0.9% sodium chloride fluid resuscitation and a fixed-rate intravenous insulin infusion, with close monitoring of potassium', true, 'Correct. DKA (hyperglycaemia, ketonaemia, acidosis) is managed with IV fluid resuscitation and a fixed-rate insulin infusion, with careful potassium monitoring and replacement as insulin drives potassium intracellularly.', 3),
('c4000000-0000-0000-0000-000000000036', 'D', 'Give IV sodium bicarbonate as first-line treatment to correct the acidosis', false, 'Ruled out because sodium bicarbonate is not routinely used in DKA; the acidosis corrects as ketosis resolves with fluids and insulin.', 4),
('c4000000-0000-0000-0000-000000000036', 'E', 'Discharge with oral hypoglycaemic medication and outpatient diabetes team follow-up', false, 'Ruled out because this is severe DKA requiring admission and IV treatment, not oral medication and discharge.', 5),
('c4000000-0000-0000-0000-000000000037', 'A', 'Arrange outpatient scrotal ultrasound over the next few days', false, 'Ruled out because testicular torsion requires immediate action; testicular viability falls rapidly with each hour of delay, so outpatient imaging is unsafe.', 1),
('c4000000-0000-0000-0000-000000000037', 'B', 'Reassure and discharge with analgesia, as this is likely epididymitis', false, 'Ruled out because the sudden onset, high-riding testis, and absent cremasteric reflex are more consistent with torsion than epididymitis, and torsion must be actively excluded urgently.', 2),
('c4000000-0000-0000-0000-000000000037', 'C', 'Give oral antibiotics for presumed epididymo-orchitis', false, 'Ruled out because antibiotics do not address a surgical emergency, and treating this as infection without excluding torsion risks losing the testis.', 3),
('c4000000-0000-0000-0000-000000000037', 'D', 'Urgent urology referral for immediate surgical exploration, without waiting for imaging if this would delay treatment', true, 'Correct. Testicular torsion is a surgical emergency with a limited window to salvage the testis; clinical suspicion (sudden severe pain, high-riding testis, absent cremasteric reflex) should prompt immediate surgical exploration rather than delaying for imaging.', 4),
('c4000000-0000-0000-0000-000000000037', 'E', 'Apply manual detorsion only, with no surgical referral required', false, 'Ruled out because even if manual detorsion is attempted, urgent surgical exploration and fixation is still required afterwards.', 5),
('c4000000-0000-0000-0000-000000000038', 'A', 'Prescribe analgesia and arrange outpatient physiotherapy', false, 'Ruled out because these are red flag features of cauda equina syndrome, a surgical emergency, not simple mechanical back pain suitable for outpatient physiotherapy.', 1),
('c4000000-0000-0000-0000-000000000038', 'B', 'Urgent MRI of the whole spine and immediate discussion with spinal surgery', true, 'Correct. Bilateral leg symptoms, saddle anaesthesia, reduced anal tone, and bladder dysfunction are red flags for cauda equina syndrome, which requires emergency MRI and urgent surgical decompression to prevent permanent neurological damage.', 2),
('c4000000-0000-0000-0000-000000000038', 'C', 'Arrange a routine outpatient MRI within the next 2 weeks', false, 'Ruled out because delay risks permanent bladder, bowel, and lower limb neurological damage; imaging must be arranged as an emergency.', 3),
('c4000000-0000-0000-0000-000000000038', 'D', 'Discharge with safety-netting advice and review by the GP in one week', false, 'Ruled out because this presentation requires emergency same-day imaging and surgical assessment, not delayed primary care review.', 4),
('c4000000-0000-0000-0000-000000000038', 'E', 'Perform a lumbar puncture to investigate for a spinal cord infection', false, 'Ruled out because the clinical picture points to a mechanical/compressive cauda equina syndrome, for which the priority investigation is emergency MRI, not lumbar puncture.', 5),
('c4000000-0000-0000-0000-000000000039', 'A', 'Urgent vascular surgery referral for emergency revascularisation, with IV heparin started immediately', true, 'Correct. Acute limb ischaemia (the 6 Ps: pain, pallor, pulselessness, paraesthesia, paralysis, perishingly cold), likely embolic given his atrial fibrillation, is a limb- and life-threatening emergency requiring immediate anticoagulation and urgent surgical or endovascular revascularisation.', 1),
('c4000000-0000-0000-0000-000000000039', 'B', 'Arrange an outpatient vascular clinic appointment within 2 weeks', false, 'Ruled out because acute limb ischaemia with sensory and motor deficit threatens limb viability within hours; this requires emergency, not outpatient, management.', 2),
('c4000000-0000-0000-0000-000000000039', 'C', 'Elevate the leg and apply a compression bandage', false, 'Ruled out because elevation and compression would further reduce arterial perfusion to an already ischaemic limb.', 3),
('c4000000-0000-0000-0000-000000000039', 'D', 'Start a statin and aspirin only, with no anticoagulation or surgical referral', false, 'Ruled out because this does not address the acute arterial occlusion; urgent revascularisation and anticoagulation are required to salvage the limb.', 4),
('c4000000-0000-0000-0000-000000000039', 'E', 'Reassure and review again in 24 hours if symptoms persist', false, 'Ruled out because a limb with sensory and motor changes from ischaemia is at imminent risk of becoming unsalvageable within this timeframe.', 5),
('c4000000-0000-0000-0000-000000000040', 'A', 'Give IV broad-spectrum antibiotics immediately as first-line treatment', false, 'Ruled out because there is no fever or evidence of infection (no leucocytes/nitrites); antibiotics are indicated for an infected obstructed system, not straightforward uncomplicated renal colic.', 1),
('c4000000-0000-0000-0000-000000000040', 'B', 'Encourage a high oral fluid intake and strict bed rest without analgesia', false, 'Ruled out because effective analgesia is the priority in acute renal colic; forced high fluid intake does not reliably aid stone passage and is not first-line management.', 2),
('c4000000-0000-0000-0000-000000000040', 'C', 'Arrange emergency surgical exploration of the ureter', false, 'Ruled out because most ureteric stones are managed conservatively or with elective urological intervention (e.g. lithotripsy), not emergency surgical exploration, unless there is infection or obstruction with deteriorating renal function.', 3),
('c4000000-0000-0000-0000-000000000040', 'D', 'Reassure and discharge with no analgesia or further investigation', false, 'Ruled out because effective analgesia and appropriate imaging to confirm the diagnosis and exclude complications are required.', 4),
('c4000000-0000-0000-0000-000000000040', 'E', 'IV or intramuscular NSAID analgesia (such as diclofenac), with imaging to confirm a suspected ureteric stone', true, 'Correct. The classic presentation of loin-to-groin colicky pain with restlessness and microscopic haematuria suggests a ureteric stone; NSAIDs are first-line analgesia, with non-contrast CT (or ultrasound in specific groups) used to confirm the diagnosis.', 5),
('c4000000-0000-0000-0000-000000000041', 'A', 'Immediate intubation given the presence of stridor', false, 'Ruled out because most croup is mild-to-moderate and managed with steroids and observation; intubation is reserved for severe, deteriorating cases with impending airway obstruction.', 1),
('c4000000-0000-0000-0000-000000000041', 'B', 'IV broad-spectrum antibiotics as first-line treatment', false, 'Ruled out because croup is typically viral, and antibiotics are not indicated unless a bacterial complication (such as bacterial tracheitis) is suspected.', 2),
('c4000000-0000-0000-0000-000000000041', 'C', 'Nebulised salbutamol as the treatment of choice', false, 'Ruled out because salbutamol targets lower airway bronchospasm, not the upper airway oedema causing croup; nebulised adrenaline (not salbutamol) is used for more severe croup.', 3),
('c4000000-0000-0000-0000-000000000041', 'D', 'A single dose of oral dexamethasone, with close observation for signs of worsening respiratory distress', true, 'Correct. This presentation (barking cough, hoarse voice, stridor) is typical of croup; a single dose of oral dexamethasone reduces upper airway oedema and symptom severity, with observation for deterioration.', 4),
('c4000000-0000-0000-0000-000000000041', 'E', 'Discharge immediately with no treatment, as symptoms are mild', false, 'Ruled out because oral dexamethasone is recommended even for mild croup, as it reduces the severity and duration of symptoms and reduces return visits.', 5),
('c4000000-0000-0000-0000-000000000042', 'A', 'Give an alpha-blocker alone and reassess for spontaneous voiding over the next 24 hours without catheterisation', false, 'Ruled out because established painful acute retention with a large residual volume requires prompt catheterisation; an alpha-blocker may aid a subsequent trial without catheter, but should not delay initial decompression.', 1),
('c4000000-0000-0000-0000-000000000042', 'B', 'Perform an urgent CT urogram before any intervention', false, 'Ruled out because catheterisation to relieve retention should not be delayed for imaging; imaging is not the first step in straightforward acute retention.', 2),
('c4000000-0000-0000-0000-000000000042', 'C', 'Restrict fluids and observe, expecting the retention to resolve spontaneously', false, 'Ruled out because acute urinary retention with a large residual volume and pain requires active decompression by catheterisation, not observation alone.', 3),
('c4000000-0000-0000-0000-000000000042', 'D', 'Refer for emergency suprapubic catheterisation as the first-line method', false, 'Ruled out because urethral catheterisation is the first-line method for acute retention; suprapubic catheterisation is reserved for cases where urethral catheterisation fails or is contraindicated.', 4),
('c4000000-0000-0000-0000-000000000042', 'E', 'Insert a urethral catheter to relieve the retention, and check renal function and for signs of obstructive uropathy', true, 'Correct. Acute urinary retention is managed with prompt catheterisation to relieve the obstruction and pain, with assessment of renal function to identify any associated obstructive nephropathy.', 5),
('c4000000-0000-0000-0000-000000000043', 'A', 'Increase inspired oxygen concentration to achieve SpO2 above 98%', false, 'Ruled out because high-concentration oxygen in COPD patients who are chronic CO2 retainers can worsen hypercapnia and acidosis by reducing hypoxic respiratory drive and altering ventilation-perfusion matching.', 1),
('c4000000-0000-0000-0000-000000000043', 'B', 'Immediately proceed to invasive mechanical ventilation without a trial of NIV', false, 'Ruled out because NIV is the first-line escalation for persisting hypercapnic acidosis in COPD unless there are contraindications or NIV has already failed.', 2),
('c4000000-0000-0000-0000-000000000043', 'C', 'Start non-invasive ventilation (NIV)', true, 'Correct. Persisting hypercapnic respiratory acidosis despite optimal medical therapy in an acute COPD exacerbation is the standard indication for non-invasive ventilation (typically BiPAP).', 3),
('c4000000-0000-0000-0000-000000000043', 'D', 'Give IV naloxone', false, 'Ruled out because there is no indication of opioid toxicity here; the respiratory failure is due to COPD exacerbation.', 4),
('c4000000-0000-0000-0000-000000000043', 'E', 'Discharge home with an increased dose of home nebulisers', false, 'Ruled out because ongoing type 2 respiratory failure with acidosis despite treatment requires escalation to NIV as an inpatient, not discharge.', 5),
('c4000000-0000-0000-0000-000000000044', 'A', 'Stop NIV immediately and manage the suspected pneumothorax with urgent chest decompression', true, 'Correct. An undrained pneumothorax is a contraindication to non-invasive ventilation, as positive pressure can rapidly enlarge it into a tension pneumothorax; NIV should be stopped and the pneumothorax treated urgently.', 1),
('c4000000-0000-0000-0000-000000000044', 'B', 'Increase the NIV pressures to improve oxygenation', false, 'Ruled out because increasing positive pressure in the presence of an undrained pneumothorax risks converting it into a life-threatening tension pneumothorax.', 2),
('c4000000-0000-0000-0000-000000000044', 'C', 'Continue NIV unchanged and arrange a routine chest X-ray in the morning', false, 'Ruled out because the clinical findings suggest an evolving pneumothorax that requires immediate action, not delayed investigation while continuing positive pressure ventilation.', 3),
('c4000000-0000-0000-0000-000000000044', 'D', 'Give IV furosemide for presumed pulmonary oedema', false, 'Ruled out because the examination findings (absent breath sounds, hyperresonance) indicate pneumothorax, not pulmonary oedema.', 4),
('c4000000-0000-0000-0000-000000000044', 'E', 'Switch to nasal high-flow oxygen at the same settings without addressing the chest findings', false, 'Ruled out because this does not treat the suspected pneumothorax, which needs urgent decompression regardless of the oxygen delivery method chosen.', 5),
('c4000000-0000-0000-0000-000000000045', 'A', 'Ventilate with high tidal volumes (12-15 mL/kg) to normalise arterial pCO2 as quickly as possible', false, 'Ruled out because high tidal volumes increase the risk of ventilator-induced lung injury (barotrauma/volutrauma) in ARDS and are specifically avoided in favour of lung-protective strategies.', 1),
('c4000000-0000-0000-0000-000000000045', 'B', 'Lung-protective ventilation with low tidal volumes (approximately 6 mL/kg predicted body weight) and adequate PEEP, accepting a degree of permissive hypercapnia', true, 'Correct. This presentation (bilateral infiltrates, PaO2/FiO2 ratio 100-200 mmHg, no cardiac cause) meets criteria for moderate ARDS; lung-protective ventilation with low tidal volumes and adequate PEEP reduces ventilator-induced lung injury, even if this means tolerating a higher pCO2.', 2),
('c4000000-0000-0000-0000-000000000045', 'C', 'Give IV furosemide as the primary treatment, as this is fluid overload rather than ARDS', false, 'Ruled out because echocardiography has excluded a cardiac cause, supporting a diagnosis of ARDS rather than cardiogenic pulmonary oedema.', 3),
('c4000000-0000-0000-0000-000000000045', 'D', 'Set PEEP to zero to maximise tidal volume delivery', false, 'Ruled out because adequate PEEP helps recruit collapsed alveoli and improve oxygenation in ARDS; removing PEEP would worsen atelectasis and hypoxaemia.', 4),
('c4000000-0000-0000-0000-000000000045', 'E', 'Extubate immediately and trial high-flow nasal oxygen only', false, 'Ruled out because this patient has moderate ARDS requiring ongoing invasive ventilatory support, not extubation.', 5),
('c4000000-0000-0000-0000-000000000046', 'A', 'Continuous positive airway pressure (CPAP)', true, 'Correct. Persisting hypoxaemic (type 1) respiratory failure from acute cardiogenic pulmonary oedema despite medical therapy is a standard indication for CPAP, which improves oxygenation by increasing alveolar recruitment and reducing venous return/preload.', 1),
('c4000000-0000-0000-0000-000000000046', 'B', 'Bilevel non-invasive ventilation (BiPAP) as first-line rather than CPAP', false, 'Ruled out because CPAP, not BiPAP, is the standard first-line non-invasive respiratory support for cardiogenic pulmonary oedema; BiPAP is preferred in hypercapnic (type 2) respiratory failure such as COPD.', 2),
('c4000000-0000-0000-0000-000000000046', 'C', 'Further IV fluid bolus to improve cardiac output', false, 'Ruled out because IV fluids would worsen pulmonary oedema and hypoxaemia in this fluid-overloaded patient.', 3),
('c4000000-0000-0000-0000-000000000046', 'D', 'Reassure and continue current oxygen therapy without escalation', false, 'Ruled out because persisting severe hypoxaemia despite maximal medical therapy requires escalation of respiratory support, not continuation of an ineffective strategy.', 4),
('c4000000-0000-0000-0000-000000000046', 'E', 'Immediate elective tracheostomy', false, 'Ruled out because tracheostomy is not an emergency airway intervention for acute pulmonary oedema; non-invasive respiratory support such as CPAP is the appropriate next step.', 5),
('c4000000-0000-0000-0000-000000000047', 'A', 'Start a regular benzodiazepine to sedate him and prevent further agitation', false, 'Ruled out because benzodiazepines are a recognised risk factor for precipitating and worsening delirium in critically ill patients and are generally avoided.', 1),
('c4000000-0000-0000-0000-000000000047', 'B', 'Apply physical restraints as the first-line management strategy', false, 'Ruled out because physical restraint is not first-line management and can worsen agitation and distress; non-pharmacological and environmental measures are prioritised first.', 2),
('c4000000-0000-0000-0000-000000000047', 'C', 'Arrange an urgent CT head as the next step, given the delirium is unexplained', false, 'Ruled out because common, reversible causes (infection, metabolic disturbance, drugs) have already been screened and excluded; further neuroimaging is not the standard next step for typical ICU delirium without focal neurological signs.', 3),
('c4000000-0000-0000-0000-000000000047', 'D', 'Discharge from critical care to a general ward immediately, as delirium does not require ongoing monitoring', false, 'Ruled out because delirium in a critically ill post-operative patient needs continued monitoring and a structured management approach, not premature discharge from a higher level of care.', 4),
('c4000000-0000-0000-0000-000000000047', 'E', 'Prioritise non-pharmacological measures (reorientation, normalising sleep-wake cycle, minimising unnecessary lines/catheters, early mobilisation) and reserve antipsychotics for severe agitation', true, 'Correct. ICU delirium is managed primarily with non-pharmacological strategies addressing reversible contributing factors (environment, sleep disruption, sensory impairment, immobility); sedative/antipsychotic medication is reserved for severe agitation causing risk to the patient or staff.', 5),
('c4000000-0000-0000-0000-000000000048', 'A', 'Nursing the patient flat to reduce the risk of pressure sores', false, 'Ruled out because nursing a ventilated patient flat increases the risk of aspiration and ventilator-associated pneumonia; a semi-recumbent position (30-45 degrees) is recommended instead.', 1),
('c4000000-0000-0000-0000-000000000048', 'B', 'Continuous deep sedation without daily interruption to keep the patient comfortable', false, 'Ruled out because continuous, uninterrupted deep sedation prolongs ventilation duration and increases ventilator-associated pneumonia risk; daily sedation holds are recommended.', 2),
('c4000000-0000-0000-0000-000000000048', 'C', 'Nursing the patient with the head of the bed elevated to 30-45 degrees, with daily sedation holds and regular oral hygiene', true, 'Correct. Elevating the head of the bed reduces aspiration risk, daily sedation holds allow assessment for earlier extubation, and regular oral/dental hygiene reduces oropharyngeal bacterial load — all core components of ventilator-associated pneumonia prevention bundles.', 3),
('c4000000-0000-0000-0000-000000000048', 'D', 'Routine prophylactic systemic antibiotics for all ventilated patients', false, 'Ruled out because routine prophylactic antibiotics are not part of standard ventilator-associated pneumonia prevention bundles and promote antimicrobial resistance.', 4),
('c4000000-0000-0000-0000-000000000048', 'E', 'Avoiding oral hygiene measures to reduce mucosal trauma', false, 'Ruled out because regular oral hygiene (including chlorhexidine mouth care in some protocols) reduces oropharyngeal bacterial colonisation and is a recommended bundle component, not something to avoid.', 5),
('c4000000-0000-0000-0000-000000000049', 'A', $x$Automatically escalate to critical care for intubation and ventilation, as this is always in the patient's best interest$x$, false, $x$Ruled out because escalation decisions should be individualised, taking into account the patient's wishes, comorbidities, and likely benefit, not applied automatically regardless of context.$x$, 1),
('c4000000-0000-0000-0000-000000000049', 'B', 'Withhold all further treatment, including oxygen and antibiotics, without further discussion', false, 'Ruled out because a ceiling of care decision does not mean withholding all treatment; appropriate ward-based treatment (oxygen, antibiotics, symptom control) should continue unless a broader palliative decision has been made.', 2),
('c4000000-0000-0000-0000-000000000049', 'C', 'Make the decision unilaterally without involving the family or wider team', false, 'Ruled out because best practice is a shared decision-making process involving the patient (where possible), family, and multidisciplinary team, not a decision made in isolation.', 3),
('c4000000-0000-0000-0000-000000000049', 'D', $x$Hold an early, honest discussion with the patient's family and the wider multidisciplinary team to agree an individualised treatment escalation plan, informed by her previously expressed wishes and likely benefit from invasive treatment$x$, true, 'Correct. Decisions about ceiling of care and escalation should be made through a shared, individualised discussion between the clinical team and patient/family, taking into account prior expressed wishes, comorbidities, and the likely benefit versus burden of invasive treatments, documented as a treatment escalation plan.', 4),
('c4000000-0000-0000-0000-000000000049', 'E', $x$Defer any decision indefinitely until the patient's condition further deteriorates$x$, false, $x$Ruled out because early, proactive discussion about ceiling of care avoids crisis decision-making and allows the patient's wishes and best interests to be properly considered in advance.$x$, 5),
('c4000000-0000-0000-0000-000000000050', 'A', 'A persistent vegetative state, which is compatible with ongoing brainstem function', false, 'Ruled out because a persistent vegetative state implies preserved brainstem reflexes and sleep-wake cycles with absent higher cortical function, which does not match the described absent brainstem reflexes and failed apnoea test.', 1),
('c4000000-0000-0000-0000-000000000050', 'B', 'Brainstem death, confirmed on formal testing by two appropriately qualified senior clinicians', true, 'Correct. Absent pupillary, corneal, gag, and cough reflexes, together with no respiratory effort on a formal apnoea test with confirmed hypercapnic stimulus, are the components of brainstem death testing; this must be performed and confirmed by two suitably senior, experienced clinicians, on two separate occasions.', 2),
('c4000000-0000-0000-0000-000000000050', 'C', 'Severe but reversible sedative drug effect explaining all findings', false, 'Ruled out because the scenario specifies he is off all sedation, and reversible causes (drugs, hypothermia, metabolic derangement) must be excluded before brainstem death testing is considered valid.', 3),
('c4000000-0000-0000-0000-000000000050', 'D', 'Locked-in syndrome, requiring alternative communication methods', false, 'Ruled out because locked-in syndrome preserves consciousness and vertical eye movements/blinking, which is inconsistent with the complete absence of brainstem reflexes described here.', 4),
('c4000000-0000-0000-0000-000000000050', 'E', 'A normal post-cardiac arrest recovery pattern, requiring no further action', false, 'Ruled out because absent brainstem reflexes and a positive apnoea test are not part of normal recovery and instead meet the criteria for a diagnosis of brainstem death.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c4000000-0000-0000-0000-000000000001', $x$Signs of base of skull fracture (panda/raccoon eyes, CSF rhinorrhoea/otorrhoea, Battle's sign) are a contraindication to nasopharyngeal airway insertion.$x$, 1),
('c4000000-0000-0000-0000-000000000001', 'Airway obstruction takes priority over all other primary survey steps.', 2),
('c4000000-0000-0000-0000-000000000001', 'A GCS of 8 or less, especially with airway compromise, prompts consideration of a definitive (intubated) airway.', 3),
('c4000000-0000-0000-0000-000000000002', 'Tension pneumothorax is a clinical diagnosis; treat immediately, do not wait for imaging.', 1),
('c4000000-0000-0000-0000-000000000002', 'Needle or finger thoracostomy decompresses the chest; a chest drain follows for definitive management.', 2),
('c4000000-0000-0000-0000-000000000002', 'Positive-pressure ventilation before decompression can rapidly worsen a tension pneumothorax.', 3),
('c4000000-0000-0000-0000-000000000003', 'Haemorrhagic shock unresponsive to initial fluids should trigger the major haemorrhage protocol with early balanced blood product transfusion, not repeated crystalloid boluses.', 1),
('c4000000-0000-0000-0000-000000000003', 'Damage-control resuscitation favours permissive hypotension and minimising crystalloid to avoid dilutional coagulopathy while arranging definitive haemorrhage control.', 2),
('c4000000-0000-0000-0000-000000000003', 'Tranexamic acid is given early as an adjunct but does not replace the need for surgical or interventional source control.', 3),
('c4000000-0000-0000-0000-000000000004', 'Midline cervical spine tenderness following a dangerous mechanism is an indication for CT cervical spine (not plain films) per NICE guidance.', 1),
('c4000000-0000-0000-0000-000000000004', 'Spinal immobilisation should be maintained until imaging or clinical clearance, regardless of a normal GCS.', 2),
('c4000000-0000-0000-0000-000000000004', 'A normal GCS does not exclude a significant cervical spine injury.', 3),
('c4000000-0000-0000-0000-000000000005', 'Major haemorrhage protocols use an empirical fixed ratio (approximately 1:1:1 red cells:FFP:platelets) early, before laboratory-guided targets are available.', 1),
('c4000000-0000-0000-0000-000000000005', 'Balanced early transfusion reduces trauma-induced coagulopathy compared with red-cell-predominant resuscitation.', 2),
('c4000000-0000-0000-0000-000000000005', 'Crystalloid should be minimised once a major haemorrhage protocol is activated.', 3),
('c4000000-0000-0000-0000-000000000006', 'Flail chest (paradoxical chest wall movement) results from segmental multiple rib fractures and is frequently associated with underlying pulmonary contusion.', 1),
('c4000000-0000-0000-0000-000000000006', 'Adequate analgesia and oxygenation are priorities; hypoventilation and secondary lung injury are the main risks, sometimes requiring ventilatory support.', 2),
('c4000000-0000-0000-0000-000000000006', 'Distinguish flail chest from tension pneumothorax, which presents with tracheal deviation, absent breath sounds, and haemodynamic compromise.', 3),
('c4000000-0000-0000-0000-000000000007', $x$Beck's triad (hypotension, muffled heart sounds, distended neck veins) plus pericardial fluid on FAST suggests cardiac tamponade.$x$, 1),
('c4000000-0000-0000-0000-000000000007', 'Traumatic tamponade needs urgent pericardial decompression and definitive surgical repair of the underlying cardiac injury.', 2),
('c4000000-0000-0000-0000-000000000007', 'Tamponade physiology is preload-dependent; diuretics or vasodilators can precipitate cardiovascular collapse.', 3),
('c4000000-0000-0000-0000-000000000008', 'Anticoagulant therapy in a patient with head injury is an indication for CT head within 1 hour, regardless of GCS.', 1),
('c4000000-0000-0000-0000-000000000008', 'NICE head injury risk factors include GCS <13 initially, GCS <15 at 2 hours, suspected skull fracture, focal neurology, repeated vomiting, post-traumatic seizure, anticoagulation, and age 65 or over with loss of consciousness/amnesia and a dangerous mechanism.', 2),
('c4000000-0000-0000-0000-000000000008', 'CT (not MRI) is the first-line investigation for suspected acute traumatic intracranial injury.', 3),
('c4000000-0000-0000-0000-000000000009', $x$Suspected sepsis with organ dysfunction (confusion, hypotension, raised lactate) requires the 'Sepsis Six' bundle within one hour: oxygen, cultures, lactate, fluids, antibiotics, and monitoring urine output.$x$, 1),
('c4000000-0000-0000-0000-000000000009', 'Antibiotics should not be delayed pending microbiology results in suspected sepsis.', 2),
('c4000000-0000-0000-0000-000000000009', 'A likely source should be identified and treated, but investigation should not delay resuscitation and empirical antibiotics.', 3),
('c4000000-0000-0000-0000-000000000010', 'Septic shock is defined as sepsis with persisting hypotension requiring vasopressors to maintain adequate perfusion despite adequate fluid resuscitation, with raised lactate.', 1),
('c4000000-0000-0000-0000-000000000010', 'Refractory hypotension after appropriate fluid resuscitation should prompt urgent critical care/ICU referral for vasopressor support and invasive monitoring.', 2),
('c4000000-0000-0000-0000-000000000010', 'Excess crystalloid beyond appropriate resuscitation targets can cause harm without correcting shock caused by vasodilation.', 3),
('c4000000-0000-0000-0000-000000000011', 'Intramuscular adrenaline is the first-line treatment for anaphylaxis and should be given immediately, without waiting for other treatments.', 1),
('c4000000-0000-0000-0000-000000000011', 'Antihistamines and steroids are adjuncts, not substitutes for adrenaline in anaphylaxis.', 2),
('c4000000-0000-0000-0000-000000000011', 'Anaphylaxis features airway/breathing/circulation compromise alongside skin changes, and requires senior help and resuscitation-area management.', 3),
('c4000000-0000-0000-0000-000000000012', 'Cardiogenic shock following extensive MI presents with hypotension, poor perfusion, and signs of pulmonary oedema, distinguishing it from hypovolaemic shock where fluids would be appropriate.', 1),
('c4000000-0000-0000-0000-000000000012', 'Aggressive fluid resuscitation can worsen pulmonary oedema in cardiogenic shock; inotropic/vasopressor support and specialist input are needed instead.', 2),
('c4000000-0000-0000-0000-000000000012', 'Early cardiology/critical care involvement is essential for consideration of mechanical circulatory support in refractory cardiogenic shock.', 3),
('c4000000-0000-0000-0000-000000000013', 'Neurogenic shock (from spinal cord injury) causes hypotension with bradycardia and warm peripheries due to loss of sympathetic vascular tone, distinguishing it from haemorrhagic shock (tachycardia, cool peripheries).', 1),
('c4000000-0000-0000-0000-000000000013', 'In trauma, haemorrhage should always be actively excluded before attributing shock to a neurogenic cause, as haemorrhage is far more common and immediately life-threatening.', 2),
('c4000000-0000-0000-0000-000000000013', 'Management of neurogenic shock focuses on maintaining spinal cord perfusion alongside spinal immobilisation and specialist referral.', 3),
('c4000000-0000-0000-0000-000000000014', 'In suspected variceal haemorrhage (known cirrhosis), terlipressin and prophylactic antibiotics should be started immediately alongside resuscitation, before endoscopy.', 1),
('c4000000-0000-0000-0000-000000000014', 'Resuscitation takes priority over endoscopy in an unstable upper GI bleed.', 2),
('c4000000-0000-0000-0000-000000000014', 'Clinical evidence of shock should guide transfusion decisions; do not wait for laboratory haemoglobin results in an unstable, actively bleeding patient.', 3),
('c4000000-0000-0000-0000-000000000015', 'Toxic shock syndrome should be considered in a young woman with fever, diffuse rash, hypotension, and multi-organ involvement, particularly with tampon use; removing the foreign material is an urgent source-control step.', 1),
('c4000000-0000-0000-0000-000000000015', 'Management follows a sepsis-type approach: cultures, fluids, and empirical broad-spectrum antibiotics without delay.', 2),
('c4000000-0000-0000-0000-000000000015', 'Toxic shock syndrome can rapidly progress to multi-organ failure, so early senior/critical care involvement is appropriate.', 3),
('c4000000-0000-0000-0000-000000000016', 'Neutropenic sepsis is a medical emergency in any patient on chemotherapy presenting with fever; empirical broad-spectrum IV antibiotics must be given within 1 hour, without waiting for blood count confirmation.', 1),
('c4000000-0000-0000-0000-000000000016', 'A clear infective source is often absent in neutropenic sepsis; this should not delay empirical treatment.', 2),
('c4000000-0000-0000-0000-000000000016', 'Any patient who has had chemotherapy within the last 6 weeks presenting with fever should be assumed to have neutropenic sepsis until proven otherwise.', 3),
('c4000000-0000-0000-0000-000000000017', 'Plasma paracetamol level plotted against time since ingestion on the treatment nomogram determines the need for acetylcysteine (NAC) in patients presenting between 4-24 hours after a single acute ingestion.', 1),
('c4000000-0000-0000-0000-000000000017', 'NAC should not be withheld pending development of deranged liver function tests, as it is most effective started early.', 2),
('c4000000-0000-0000-0000-000000000017', 'Activated charcoal may be considered within 1 hour of ingestion but does not replace the need for NAC when the level is above the treatment line.', 3),
('c4000000-0000-0000-0000-000000000018', 'The triad of respiratory depression, pinpoint pupils, and reduced consciousness suggests opioid toxicity; naloxone is the specific reversal agent.', 1),
('c4000000-0000-0000-0000-000000000018', $x$Airway and ventilatory support should not be delayed while awaiting naloxone's effect, especially with significant hypoxia.$x$, 2),
('c4000000-0000-0000-0000-000000000018', 'Naloxone has a shorter half-life than many opioids, so repeat dosing or an infusion may be needed, and patients require a period of monitoring after reversal.', 3),
('c4000000-0000-0000-0000-000000000019', 'Flumazenil (benzodiazepine antagonist) should be avoided or used with great caution in chronic benzodiazepine users, as it can precipitate acute withdrawal seizures.', 1),
('c4000000-0000-0000-0000-000000000019', 'Most benzodiazepine overdoses are managed supportively (airway and breathing monitoring) rather than with reversal agents.', 2),
('c4000000-0000-0000-0000-000000000019', 'Flumazenil has a short half-life relative to many benzodiazepines, so re-sedation can occur even after apparent reversal.', 3),
('c4000000-0000-0000-0000-000000000020', 'Tricyclic antidepressant overdose causes sodium channel blockade; QRS widening (over 100ms) indicates significant cardiotoxicity and risk of ventricular arrhythmia.', 1),
('c4000000-0000-0000-0000-000000000020', 'IV sodium bicarbonate is the specific treatment for tricyclic-induced QRS widening/arrhythmia, working by increasing extracellular sodium and alkalinising the serum.', 2),
('c4000000-0000-0000-0000-000000000020', 'Further sodium channel-blocking antiarrhythmics are contraindicated in tricyclic overdose as they worsen cardiotoxicity.', 3),
('c4000000-0000-0000-0000-000000000021', 'Urinary alkalinisation with IV sodium bicarbonate enhances renal elimination of salicylate by ion-trapping it in its ionised form within alkaline urine.', 1),
('c4000000-0000-0000-0000-000000000021', 'Haemodialysis is reserved for severe salicylate poisoning (very high levels, renal impairment, refractory acidosis, pulmonary oedema, or significant CNS toxicity), not routine use.', 2),
('c4000000-0000-0000-0000-000000000021', 'Salicylate overdose classically causes an early respiratory alkalosis (from direct respiratory centre stimulation) alongside a metabolic acidosis.', 3),
('c4000000-0000-0000-0000-000000000022', 'High-flow 100% oxygen is first-line treatment in carbon monoxide poisoning, as it accelerates dissociation of carbon monoxide from haemoglobin.', 1),
('c4000000-0000-0000-0000-000000000022', 'Pregnant women are at particular risk from carbon monoxide poisoning because fetal haemoglobin has a higher affinity for carbon monoxide, so a lower threshold for hyperbaric oxygen and specialist advice applies.', 2),
('c4000000-0000-0000-0000-000000000022', 'Carboxyhaemoglobin levels help assess severity but symptoms and clinical context guide urgency of treatment, not level alone.', 3),
('c4000000-0000-0000-0000-000000000023', $x$Visual disturbance ('snowstorm vision') with a high anion gap metabolic acidosis and raised osmolar gap after ingesting illicit/homemade alcohol strongly suggests methanol poisoning.$x$, 1),
('c4000000-0000-0000-0000-000000000023', 'Fomepizole (or ethanol as an alternative) inhibits alcohol dehydrogenase, preventing conversion of methanol/ethylene glycol into their toxic metabolites.', 2),
('c4000000-0000-0000-0000-000000000023', 'Severe cases with significant acidosis or end-organ effects require haemodialysis, and urgent specialist/poisons unit advice should be sought.', 3),
('c4000000-0000-0000-0000-000000000024', 'Desferrioxamine is the specific chelating agent for significant iron toxicity, indicated with systemic symptoms, shock, or markedly elevated serum iron levels.', 1),
('c4000000-0000-0000-0000-000000000024', 'Activated charcoal does not bind iron and has no role in iron overdose management.', 2),
('c4000000-0000-0000-0000-000000000024', 'Whole bowel irrigation may be considered for large iron tablet ingestions to limit ongoing absorption, particularly with tablets visible on imaging.', 3),
('c4000000-0000-0000-0000-000000000025', 'IV glucagon is a key treatment for beta-blocker overdose with refractory bradycardia/hypotension, as it increases intracellular cAMP independent of the blocked beta-receptor.', 1),
('c4000000-0000-0000-0000-000000000025', 'High-dose insulin-euglycaemia therapy is another treatment used for severe beta-blocker (and calcium channel blocker) overdose refractory to initial measures.', 2),
('c4000000-0000-0000-0000-000000000025', 'Atropine may have limited effect in beta-blocker overdose because the bradycardia is caused by receptor blockade rather than purely vagal tone.', 3),
('c4000000-0000-0000-0000-000000000026', 'Any patient with reduced consciousness should have capillary glucose checked immediately.', 1),
('c4000000-0000-0000-0000-000000000026', 'IV dextrose (or IM glucagon if no IV access) is the treatment for severe symptomatic hypoglycaemia when the patient cannot safely take oral carbohydrate.', 2),
('c4000000-0000-0000-0000-000000000026', 'After initial correction, longer-acting carbohydrate should be given to prevent rebound hypoglycaemia, and the underlying cause addressed.', 3),
('c4000000-0000-0000-0000-000000000027', 'Status epilepticus is defined as a seizure lasting more than 5 minutes, or recurrent seizures without recovery of consciousness between them; it requires active drug treatment.', 1),
('c4000000-0000-0000-0000-000000000027', 'First-line treatment is IV benzodiazepines; if seizures persist, second-line agents are used, escalating to general anaesthesia/intubation only for refractory status.', 2),
('c4000000-0000-0000-0000-000000000027', 'The IV (or buccal/rectal if no IV access) route is preferred over oral medication for rapid effect during an ongoing seizure.', 3),
('c4000000-0000-0000-0000-000000000028', 'A brief period of confusion and drowsiness (post-ictal state) is expected after a generalised seizure and does not itself indicate ongoing status epilepticus.', 1),
('c4000000-0000-0000-0000-000000000028', 'Management focuses on airway protection, safety, and monitoring during natural recovery, rather than further anticonvulsant treatment.', 2),
('c4000000-0000-0000-0000-000000000028', 'Atypical features (prolonged recovery, focal neurological deficit, head injury during the seizure, first seizure) should prompt further investigation.', 3),
('c4000000-0000-0000-0000-000000000029', 'Alcohol withdrawal seizures typically occur 24-48 hours after the last drink and are accompanied by autonomic hyperactivity (tremor, tachycardia, hypertension, sweating).', 1),
('c4000000-0000-0000-0000-000000000029', $x$Management includes treating the acute seizure, starting a reducing benzodiazepine regimen for withdrawal, and giving thiamine to prevent Wernicke's encephalopathy.$x$, 2),
('c4000000-0000-0000-0000-000000000029', 'Alcohol withdrawal seizures raise concern for progression to delirium tremens, and inpatient monitoring is usually required.', 3),
('c4000000-0000-0000-0000-000000000030', 'Hepatic encephalopathy should be suspected in a patient with known liver disease presenting with confusion and asterixis; constipation is a common precipitant due to increased ammonia absorption.', 1),
('c4000000-0000-0000-0000-000000000030', 'Lactulose is first-line treatment to reduce colonic ammonia production/absorption, alongside treating any other precipitant.', 2),
('c4000000-0000-0000-0000-000000000030', 'All patients with suspected hepatic encephalopathy should be screened for common precipitants, particularly infection and gastrointestinal bleeding.', 3),
('c4000000-0000-0000-0000-000000000031', 'CT head has its highest sensitivity for subarachnoid haemorrhage within the first 6 hours of symptom onset; sensitivity decreases thereafter.', 1),
('c4000000-0000-0000-0000-000000000031', 'Lumbar puncture for xanthochromia should be performed at least 12 hours after headache onset if CT is normal and subarachnoid haemorrhage is still suspected.', 2),
('c4000000-0000-0000-0000-000000000031', $x$Thunderclap headache (sudden, severe, 'worst ever') is a red flag requiring urgent investigation to exclude subarachnoid haemorrhage.$x$, 3),
('c4000000-0000-0000-0000-000000000032', 'Features favouring a non-epileptic (dissociative/psychogenic) seizure include closed eyes during the event, fluctuating motor activity, longer duration, pelvic thrusting, and rapid return to full awareness without post-ictal confusion.', 1),
('c4000000-0000-0000-0000-000000000032', 'Epileptic seizures more typically show open eyes, stereotyped progression, and a post-ictal period of confusion or drowsiness.', 2),
('c4000000-0000-0000-0000-000000000032', 'Video-EEG telemetry is the gold-standard investigation to distinguish epileptic from non-epileptic attacks when the diagnosis remains unclear.', 3),
('c4000000-0000-0000-0000-000000000033', 'Severe symptomatic hyponatraemia (seizure, significant confusion) is a medical emergency requiring urgent correction, typically with small-volume hypertonic saline under senior/specialist guidance.', 1),
('c4000000-0000-0000-0000-000000000033', 'Correction of hyponatraemia should be carefully controlled and not overly rapid, as this risks osmotic demyelination syndrome, particularly in chronic hyponatraemia.', 2),
('c4000000-0000-0000-0000-000000000033', 'Thiazide diuretics and SSRIs are both recognised causes of drug-induced hyponatraemia, especially in older adults.', 3),
('c4000000-0000-0000-0000-000000000034', 'Suspected bacterial meningitis, especially with a non-blanching rash suggesting meningococcal disease, requires immediate empirical IV antibiotics without waiting for lumbar puncture or CT.', 1),
('c4000000-0000-0000-0000-000000000034', 'A non-blanching purpuric rash with fever and meningism is a red flag for meningococcal septicaemia and needs urgent treatment.', 2),
('c4000000-0000-0000-0000-000000000034', 'Lumbar puncture may be deferred or contraindicated with signs of raised intracranial pressure, reduced GCS, or cardiovascular instability, but this should never delay antibiotic administration.', 3),
('c4000000-0000-0000-0000-000000000035', 'Acute severe asthma features include inability to complete sentences, RR >25/min, HR >110 bpm, and PEF 33-50% of predicted or best.', 1),
('c4000000-0000-0000-0000-000000000035', 'Life-threatening asthma features (silent chest, cyanosis, exhaustion, arrhythmia, hypotension, confusion/coma, PEF <33%) mandate senior/critical care involvement and consideration of intubation.', 2),
('c4000000-0000-0000-0000-000000000035', 'Early systemic corticosteroids alongside repeated bronchodilator nebulisers reduce relapse and should not be delayed in a severe exacerbation.', 3),
('c4000000-0000-0000-0000-000000000036', 'DKA is diagnosed by the triad of hyperglycaemia, ketonaemia (or significant ketonuria), and acidosis (venous pH <7.3 or bicarbonate <15 mmol/L).', 1),
('c4000000-0000-0000-0000-000000000036', 'Management is IV fluid resuscitation plus a fixed-rate IV insulin infusion, with regular monitoring and replacement of potassium as it shifts intracellularly.', 2),
('c4000000-0000-0000-0000-000000000036', 'Precipitants such as infection or missed insulin doses should be identified and treated, but this must not delay fluid and insulin therapy.', 3),
('c4000000-0000-0000-0000-000000000037', 'Testicular torsion is a surgical emergency; testicular salvage rates fall sharply after 6 hours of ischaemia, so urgent surgical exploration should not be delayed for imaging if this would waste time.', 1),
('c4000000-0000-0000-0000-000000000037', 'Sudden severe onset, a high-riding or horizontal testis, and loss of the cremasteric reflex favour torsion over epididymo-orchitis, which more typically has a gradual onset with urinary symptoms and fever.', 2),
('c4000000-0000-0000-0000-000000000037', 'Any doubt about the diagnosis should still prompt urgent urological referral, as missed torsion results in testicular loss.', 3),
('c4000000-0000-0000-0000-000000000038', 'Red flags for cauda equina syndrome include bilateral leg symptoms, saddle anaesthesia, bladder or bowel dysfunction, and reduced anal tone.', 1),
('c4000000-0000-0000-0000-000000000038', 'Suspected cauda equina syndrome requires emergency MRI of the whole spine and urgent surgical referral, as delayed decompression risks permanent neurological deficit.', 2),
('c4000000-0000-0000-0000-000000000038', 'A normal-appearing gait or ability to walk does not exclude cauda equina syndrome; specific red flag symptoms and signs should be actively sought.', 3),
('c4000000-0000-0000-0000-000000000039', 'Acute limb ischaemia presents with the 6 Ps: pain, pallor, pulselessness, paraesthesia, paralysis, and a perishingly cold limb; sensory and motor deficits indicate advancing, limb-threatening ischaemia.', 1),
('c4000000-0000-0000-0000-000000000039', 'Atrial fibrillation without anticoagulation is a common source of embolism causing acute limb ischaemia.', 2),
('c4000000-0000-0000-0000-000000000039', 'Immediate IV heparin and urgent vascular referral for revascularisation are required; delay risks irreversible tissue loss and amputation.', 3),
('c4000000-0000-0000-0000-000000000040', 'Loin-to-groin colicky pain with restlessness and microscopic haematuria is the classic presentation of a ureteric stone; NSAIDs are first-line analgesia.', 1),
('c4000000-0000-0000-0000-000000000040', 'Fever or signs of infection in suspected renal colic suggest an infected obstructed system, an emergency requiring urgent decompression and antibiotics, distinct from uncomplicated colic.', 2),
('c4000000-0000-0000-0000-000000000040', 'Non-contrast CT is the standard confirmatory imaging for suspected renal/ureteric stones in most adults; ultrasound may be preferred in pregnancy or children.', 3),
('c4000000-0000-0000-0000-000000000041', 'Croup classically presents with a barking cough, hoarse voice, and inspiratory stridor, usually preceded by coryzal symptoms, most commonly in children aged 6 months to 6 years.', 1),
('c4000000-0000-0000-0000-000000000041', 'A single dose of oral dexamethasone is recommended for children with croup of any severity to reduce symptom duration and severity.', 2),
('c4000000-0000-0000-0000-000000000041', 'Nebulised adrenaline is reserved for more severe croup with marked stridor/distress at rest; agitating the child (e.g. for examination) should be minimised as this can worsen airway obstruction.', 3),
('c4000000-0000-0000-0000-000000000042', 'Acute urinary retention is managed with prompt urethral catheterisation to relieve pain and obstruction, checking renal function afterward for evidence of obstructive uropathy.', 1),
('c4000000-0000-0000-0000-000000000042', 'Benign prostatic hyperplasia is a common cause of acute retention in older men, but other causes (constipation, medications, infection, neurological disease) should also be considered.', 2),
('c4000000-0000-0000-0000-000000000042', 'Suprapubic catheterisation is reserved for failed or contraindicated urethral catheterisation, not as the routine first-line approach.', 3),
('c4000000-0000-0000-0000-000000000043', 'Persisting hypercapnic respiratory acidosis despite optimal medical therapy in an acute COPD exacerbation is the standard indication for NIV.', 1),
('c4000000-0000-0000-0000-000000000043', 'Uncontrolled high-flow oxygen in COPD patients who are chronic CO2 retainers risks worsening hypercapnia and acidosis; controlled oxygen therapy targeting SpO2 88-92% is used instead.', 2),
('c4000000-0000-0000-0000-000000000043', 'NIV failure (worsening acidosis, reduced consciousness, exhaustion) should prompt urgent senior/critical care review for consideration of invasive ventilation.', 3),
('c4000000-0000-0000-0000-000000000044', 'An undrained pneumothorax is a contraindication to non-invasive ventilation because positive pressure can precipitate a tension pneumothorax.', 1),
('c4000000-0000-0000-0000-000000000044', 'Sudden deterioration on NIV with absent breath sounds and hyperresonance should prompt immediate suspicion of pneumothorax and cessation of positive pressure until it is decompressed.', 2),
('c4000000-0000-0000-0000-000000000044', 'Other relative contraindications to NIV include facial trauma/burns, vomiting, life-threatening hypoxaemia, and reduced consciousness with inability to protect the airway.', 3),
('c4000000-0000-0000-0000-000000000045', 'ARDS is defined by acute onset bilateral pulmonary infiltrates, a PaO2/FiO2 ratio of 300 mmHg or less, and exclusion of cardiac failure/fluid overload as the sole cause.', 1),
('c4000000-0000-0000-0000-000000000045', 'Lung-protective ventilation (low tidal volumes around 6 mL/kg predicted body weight, adequate PEEP) reduces ventilator-induced lung injury and improves outcomes in ARDS.', 2),
('c4000000-0000-0000-0000-000000000045', 'Permissive hypercapnia (tolerating a higher than normal pCO2) is often accepted as a trade-off to avoid the lung damage caused by higher tidal volumes/pressures.', 3),
('c4000000-0000-0000-0000-000000000046', 'CPAP is the standard non-invasive respiratory support for hypoxaemic (type 1) respiratory failure from acute cardiogenic pulmonary oedema, improving oxygenation and reducing preload/afterload.', 1),
('c4000000-0000-0000-0000-000000000046', 'BiPAP is preferred over CPAP for hypercapnic (type 2) respiratory failure, such as COPD exacerbations, as it provides additional ventilatory support to help clear CO2.', 2),
('c4000000-0000-0000-0000-000000000046', 'Failure to improve on CPAP should prompt urgent senior/critical care review for consideration of invasive ventilation.', 3),
('c4000000-0000-0000-0000-000000000047', 'ICU delirium is managed primarily through non-pharmacological measures: reorientation, correcting sensory impairment, restoring day-night cycles, minimising invasive lines, and early mobilisation.', 1),
('c4000000-0000-0000-0000-000000000047', 'Benzodiazepines are a recognised risk factor for delirium in critically ill patients and should generally be avoided when managing agitation from delirium.', 2),
('c4000000-0000-0000-0000-000000000047', 'Reversible precipitants (infection, metabolic derangement, pain, drug effects, sleep deprivation) should always be actively screened for and treated in a delirious critically ill patient.', 3),
('c4000000-0000-0000-0000-000000000048', 'Ventilator-associated pneumonia prevention bundles include semi-recumbent positioning (head of bed 30-45 degrees), daily sedation holds, regular oral hygiene, and assessment of extubation readiness.', 1),
('c4000000-0000-0000-0000-000000000048', 'Minimising the duration of mechanical ventilation through daily sedation holds and weaning assessment is one of the most effective ways to reduce ventilator-associated pneumonia risk.', 2),
('c4000000-0000-0000-0000-000000000048', 'Routine prophylactic systemic antibiotics are not part of standard prevention bundles and are avoided due to the risk of promoting resistant organisms.', 3),
('c4000000-0000-0000-0000-000000000049', $x$Treatment escalation and ceiling of care decisions should be individualised, considering the patient's previously expressed wishes, comorbidities, frailty, and the likely benefit versus burden of invasive treatment.$x$, 1),
('c4000000-0000-0000-0000-000000000049', 'A ceiling of care decision does not mean withdrawing all treatment; appropriate ward-level care (oxygen, antibiotics, symptom control) typically continues unless a separate palliative decision is made.', 2),
('c4000000-0000-0000-0000-000000000049', 'Early, honest, shared discussions involving the patient (where possible), family, and multidisciplinary team reduce the need for rushed decisions during a crisis.', 3),
('c4000000-0000-0000-0000-000000000050', 'Brainstem death testing assesses pupillary, corneal, vestibulo-ocular, gag, and cough reflexes, plus a formal apnoea test looking for respiratory effort despite a rise in arterial pCO2.', 1),
('c4000000-0000-0000-0000-000000000050', 'Reversible causes (sedative or neuromuscular blocking drugs, hypothermia, severe metabolic or endocrine disturbance) must be excluded before brainstem death testing is undertaken.', 2),
('c4000000-0000-0000-0000-000000000050', 'Testing must be performed and independently confirmed by two suitably senior and experienced clinicians, on two separate occasions, before brainstem death is diagnosed.', 3);
